<?php
/** TEMP PS S1613 run e5d — D: deploy darbalaukis v3.13 (4 b64 dalys, md5 + token, gyvo failo sargas v3.12); T (naujas procesas): vėlavimo laiško vienetai (darbo dienos, Velykos, 14:00), simuliuotos dienos (Sa · Pr · An) ribai, dublis, Klausimuose; gaudyklė prior. 4; cron planas; skydelis ajax (nonce su sesija); Playwright Surinkti AV */
add_action('init', function(){
  if (!isset($_GET['ps_e5d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e5d'])); $o=array('v'=>'S1613 e5d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $c4='';
    $p1=@file_get_contents($bk.'/dl-v313.part1'); $p2=@file_get_contents($bk.'/dl-v313.part2'); $p3=@file_get_contents($bk.'/dl-v313.part3'); $o['parts']=array(strlen((string)$p1),strlen((string)$p2),strlen((string)$p3),strlen($c4));
    $code=base64_decode($p1.$p2.$p3.$c4,true); $o['bytes']=strlen((string)$code); $o['md5']=md5((string)$code);
    if ($o['md5']!=='ae3d3416f288c4cb1bb2b65b18799c63') { $o['STOP']='md5 nesutampa'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=md5_file($t);
    if ($o['buvo']!=='b20740b6ee0abcc8930a5c1eb0f74246') { $o['STOP']='gyvas ne v3.12 ('.$o['buvo'].')'; $J($o); }
    $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v312-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); @unlink($bk.'/dl-v313.part1'); @unlink($bk.'/dl-v313.part2'); @unlink($bk.'/dl-v313.part3');
  }
  if($f==='T'){
    $o['versija']=Petshop_Darbalaukis::VERSIJA; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'); $o['dev_zurnalas_pries']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    update_option('ps_e5_mail',array(),false);
    add_filter('pre_wp_mail',function($r,$a){ $m=get_option('ps_e5_mail',array()); $m[]=array('to'=>is_array($a['to'])?implode(',',$a['to']):$a['to'],'s'=>$a['subject'],'b'=>mb_substr(preg_replace('/\s+/',' ',wp_strip_all_tags((string)$a['message'])),0,520)); update_option('ps_e5_mail',$m,false); return true; },4,2);
    $DL='Petshop_Darbalaukis'; $tz=wp_timezone();
    // vienetai
    $o['velykos']=array(2026=>$DL::velykos(2026),2027=>$DL::velykos(2027),2025=>$DL::velykos(2025));
    $o['darbo']=array(); foreach(array('2026-09-04','2026-09-05','2026-09-06','2026-09-07','2026-11-01','2026-11-02','2026-04-06','2026-04-07','2026-12-24','2026-02-16') as $d){ $o['darbo'][$d]=$DL::darbo_diena($d); }
    $o['pilnos']=array('08-31→09-04'=>$DL::pilnos_darbo_dienos('2026-08-31','2026-09-04'),'09-04→09-07'=>$DL::pilnos_darbo_dienos('2026-09-04','2026-09-07'),'09-04→09-10'=>$DL::pilnos_darbo_dienos('2026-09-04','2026-09-10'),'09-02→09-08'=>$DL::pilnos_darbo_dienos('2026-09-02','2026-09-08'),'09-03→09-08'=>$DL::pilnos_darbo_dienos('2026-09-03','2026-09-08'),'04-02→04-09'=>$DL::pilnos_darbo_dienos('2026-04-02','2026-04-09'),'09-04→09-04'=>$DL::pilnos_darbo_dienos('2026-09-04','2026-09-04'));
    $o['kitas_1400']=array('nuo_dabar'=>wp_date('Y-m-d H:i',$DL::kitas_1400()),'nuo_13_59'=>wp_date('Y-m-d H:i',$DL::kitas_1400((new DateTime('2026-09-04 13:59',$tz))->getTimestamp())),'nuo_14_00'=>wp_date('Y-m-d H:i',$DL::kitas_1400((new DateTime('2026-09-04 14:00',$tz))->getTimestamp())));
    $ns=wp_next_scheduled('ps_velavimo_laiskai'); $o['cron_planas']=$ns?wp_date('Y-m-d H:i',$ns):null; $o['cron_venipak']=wp_date('Y-m-d H:i',(int)wp_next_scheduled('ps_venipak_sekimas'));
    // kandidatai su apmokėjimo datomis
    $rm=new ReflectionMethod($DL,'velavimo_kandidatai'); $rm->setAccessible(true); $kand=$rm->invoke(null); $o['kandidatai']=array();
    foreach($kand as $id){ $x=wc_get_order($id); $dp=$x->get_date_paid()?:$x->get_date_created(); $dpv=clone $dp; $dpv->setTimezone($tz); $o['kandidatai'][$id]=$x->get_status().' '.$dpv->format('m-d D').' '.$x->get_billing_email().' kl='.(string)$x->get_meta('_ps_klaus_laukti'); }
    // pasirinkimas: pirmas apmokėtas 09-02, pirmas 09-03, + 35421 (Klausimuose — variklio „Tiekėjas vėluoja“)
    $a=null;$b=null; foreach($kand as $id){ $x=wc_get_order($id); $dp=$x->get_date_paid()?:$x->get_date_created(); $dpv=clone $dp; $dpv->setTimezone($tz); $md=$dpv->format('m-d'); if($id!=35421 && $md==='09-02' && !$a) $a=$id; if($id!=35421 && $md==='09-03' && !$b) $b=$id; }
    $ids=array_values(array_filter(array($a,$b,35421))); $o['test_ids']=$ids;
    $bk=function($id){ $x=wc_get_order($id); return array('st'=>$x->get_status(),'vel'=>(string)$x->get_meta('_ps_velavimo_laiskas'),'iss'=>(string)$x->get_meta('_ps_dalys_issiusta')); };
    foreach($ids as $id){ $o['pries'][$id]=$bk($id); }
    // a) šeštadienis
    $o['sim_sa']=$DL::velavimo_laiskai((new DateTime('2026-09-05 14:00',$tz))->getTimestamp(),$ids);
    // b) pirmadienis 09-07 (09-02 → Kt,Pn = 2; 09-03 → Pn = 1) — visi praleisti
    $o['sim_pr']=$DL::velavimo_laiskai((new DateTime('2026-09-07 14:00',$tz))->getTimestamp(),$ids); $o['mail_po_pr']=count(get_option('ps_e5_mail',array()));
    // c) antradienis 09-08 (09-02 → Kt,Pn,Pr = 3 → laiškas; 09-03 → 2 → ne; 35421 → Klausimuose)
    $o['sim_an']=$DL::velavimo_laiskai((new DateTime('2026-09-08 14:00',$tz))->getTimestamp(),$ids); $o['mail_po_an']=count(get_option('ps_e5_mail',array()));
    // d) dublis
    $o['sim_an2']=$DL::velavimo_laiskai((new DateTime('2026-09-08 14:00',$tz))->getTimestamp(),$ids); $o['mail_po_an2']=count(get_option('ps_e5_mail',array()));
    foreach($ids as $id){ $o['po'][$id]=$bk($id); }
    $o['notes_a']=$a?array_map(function($n){ return $n->date_created->date('H:i').' '.mb_substr($n->content,0,220); },array_slice(wc_get_order_notes(array('order_id'=>$a,'limit'=>2)),0,2)):null;
    $o['ivykiai_a']=$a?$wpdb->get_results($wpdb->prepare("SELECT veiksmas, kanalas, rezultatas, LEFT(po,200) po FROM {$p}ps_uzsakymu_ivykiai WHERE uzsakymas=%d ORDER BY id DESC LIMIT 2",$a),ARRAY_A):null;
    $o['laiskai']=array_map(function($m){ return $m['to'].' | '.$m['s'].' | '.$m['b']; },get_option('ps_e5_mail',array())); delete_option('ps_e5_mail'); $o['dev_zurnalas_po']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    $o['paskutinis_opcija']=get_option('ps_velavimo_laiskai_paskutinis'); // turi būti tuščia — testai opcijos nerašo
    // skydelis kaip testuotojas (nonce su sesijos raktu — e8d šablonas)
    $tu=get_user_by('login','testuotojas'); $uid=$tu->ID; $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($uid)->create($exp);
    $li=wp_generate_auth_cookie($uid,$exp,'logged_in',$tok); $_COOKIE[LOGGED_IN_COOKIE]=$li; wp_set_current_user($uid);
    $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>$li)));
    $n=wp_create_nonce('ps_dl_zurnalas');
    if($a){ $r=wp_remote_get(admin_url('admin-ajax.php?action=ps_dl_skydelis&id='.$a.'&n='.$n),array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $bd=is_wp_error($r)?'':wp_remote_retrieve_body($r); $j=json_decode($bd,true); $o['skydelis']=array('code'=>wp_remote_retrieve_response_code($r),'pastaba'=>$j['data']['pastaba']??null,'kl'=>$j['data']['klausimas']??null,'kur'=>$j['data']['kur']??null); }
    wp_set_current_user(0);
    $o['cookies']=array(); foreach($cs as $c){ $o['cookies'][]=array('name'=>$c->name,'value'=>$c->value); }
    $o['shots']=array(array('n'=>'s1613_e5_surinkti_av','u'=>admin_url('admin.php?page=ps-desk&eile=surinkti'),'w'=>1400,'full'=>true,'eval'=>"({pills:[...document.querySelectorAll('.dl-pill-e')].map(x=>x.innerText).slice(0,10)})"));
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  $J($o);
},99);
